"""Font discovery, substitution and metrics.

Word documents name fonts that may not exist on the machine doing the
conversion, so this module keeps an index of the installed fonts, maps missing
families onto metric-compatible substitutes, registers what it needs with
ReportLab and falls back per character when a glyph is missing.
"""
from __future__ import annotations

import hashlib
import json
import os
import sys
import tempfile
from dataclasses import dataclass
from importlib import util as import_util
from typing import Optional

from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont, TTFError

from .ttf import FontInfo, collection_offsets, read_font

FONT_EXTENSIONS = ('.ttf', '.ttc', '.otf', '.TTF', '.TTC', '.OTF')

